import { createContext, createElement } from 'react';
import { Web3AuthNoModal } from '../../noModal.js';
import { useWeb3AuthInnerContextValue } from './useWeb3AuthInnerContextValue.js';

const Web3AuthInnerContext = createContext(null);
function Web3AuthInnerProvider(params) {
  const {
    children,
    config,
    initialState
  } = params;
  const {
    web3AuthOptions
  } = config;
  const value = useWeb3AuthInnerContextValue({
    Web3AuthConstructor: Web3AuthNoModal,
    web3AuthOptions,
    initialState
  });
  return createElement(Web3AuthInnerContext.Provider, {
    value
  }, children);
}

export { Web3AuthInnerContext, Web3AuthInnerProvider };
